"""Validate competitors/raw/bmw_baseline_outlook.jsonl (schema checks only)."""
import json
import sys
from collections import Counter

path = sys.argv[1]
themes_path = sys.argv[2]
themes = {t["id"] for t in json.load(open(themes_path))["themes"]}
FEATURES = {
    "F01_display_layout": "hmi_infotainment", "F02_hud": "hmi_infotainment",
    "F03_physical_climate_controls": "climate", "F04_voice_assistant": "hmi_infotainment",
    "F05_wireless_carplay_aa": "connectivity_app_digital", "F06_ota_updates": "connectivity_app_digital",
    "F07_digital_key": "access_locking", "F08_hands_free_highway": "adas_parking",
    "F09_automated_parking": "adas_parking", "F10_ventilated_front_seats": "seats_comfort",
    "F11_massage_seats": "seats_comfort", "F12_rear_comfort": "seats_comfort",
    "F13_air_suspension": "ride_handling", "F14_rear_wheel_steering": "ride_handling",
    "F15_bev_range": "range_charging_efficiency", "F16_dc_charging": "range_charging_efficiency",
    "F17_rear_space": "space_practicality", "F18_trunk_volume": "space_practicality",
    "F19_premium_audio": "audio_acoustics", "F20_panoramic_roof": "interior_design_quality",
}
EQ_FIELDS = ["record_id", "kind", "market", "brand", "model", "generation", "trim_scope", "feature",
             "theme", "availability", "value", "source_type", "url", "as_of", "evidence_tier", "notes"]
OL_FIELDS = ["record_id", "kind", "markets", "brand", "model", "current_generation", "announcement",
             "customer_facing_changes", "theme", "url", "published", "evidence_tier", "confidence"]
errors = []
ids = Counter()
kinds = Counter()
per = Counter()
for n, line in enumerate(open(path, encoding="utf-8"), 1):
    line = line.strip()
    if not line:
        errors.append(f"line {n}: empty line")
        continue
    try:
        r = json.loads(line)
    except Exception as e:
        errors.append(f"line {n}: JSON error {e}")
        continue
    ids[r.get("record_id")] += 1
    k = r.get("kind")
    kinds[k] += 1
    if r.get("theme") not in themes:
        errors.append(f"line {n}: bad theme {r.get('theme')}")
    if k == "equipment":
        for f in EQ_FIELDS:
            if f not in r:
                errors.append(f"line {n}: missing {f}")
        if not str(r.get("record_id", "")).startswith("bmw_baseline_outlook-E"):
            errors.append(f"line {n}: bad id {r.get('record_id')}")
        if r.get("market") not in {"EU", "US", "CN"}:
            errors.append(f"line {n}: bad market")
        if r.get("availability") not in {"standard", "optional", "not_available", "unknown"}:
            errors.append(f"line {n}: bad availability {r.get('availability')}")
        if r.get("feature") not in FEATURES:
            errors.append(f"line {n}: bad feature {r.get('feature')}")
        elif FEATURES[r["feature"]] != r.get("theme"):
            errors.append(f"line {n}: theme {r.get('theme')} != {FEATURES[r['feature']]} for {r['feature']}")
        if r.get("source_type") not in {"manufacturer", "press_review"}:
            errors.append(f"line {n}: bad source_type")
        if r.get("evidence_tier") not in {"C", "B"}:
            errors.append(f"line {n}: bad tier")
        if r.get("source_type") == "manufacturer" and r.get("evidence_tier") != "C":
            errors.append(f"line {n}: manufacturer source should be tier C")
        if r.get("source_type") == "press_review" and r.get("evidence_tier") != "B":
            errors.append(f"line {n}: press source should be tier B")
        per[(r.get("market"), r.get("feature"))] += 1
    elif k == "outlook":
        for f in OL_FIELDS:
            if f not in r:
                errors.append(f"line {n}: missing {f}")
        if not str(r.get("record_id", "")).startswith("bmw_baseline_outlook-O"):
            errors.append(f"line {n}: bad id")
        if not isinstance(r.get("markets"), list) or not set(r.get("markets", [])) <= {"EU", "US", "CN"}:
            errors.append(f"line {n}: bad markets")
        if r.get("confidence") not in {"announced", "reported", "rumoured"}:
            errors.append(f"line {n}: bad confidence")
        if r.get("evidence_tier") != "D":
            errors.append(f"line {n}: outlook tier must be D")
        if not isinstance(r.get("customer_facing_changes"), list):
            errors.append(f"line {n}: customer_facing_changes must be list")
    else:
        errors.append(f"line {n}: unknown kind {k}")
    if not str(r.get("url", "")).strip():
        errors.append(f"line {n}: empty url")
dups = [i for i, c in ids.items() if c > 1]
if dups:
    errors.append(f"duplicate ids: {dups}")
print("kinds:", dict(kinds))
markets = Counter(m for (m, _f) in per.elements())
print("equipment per market:", dict(markets))
for m in ["EU", "US", "CN"]:
    missing = [f for f in FEATURES if (m, f) not in per]
    if markets.get(m):
        print(f"{m} missing features: {missing}")
print("ERRORS:" if errors else "OK", *errors, sep="\n")

